/// Checks if `sub` matches `main` starting at index `start`.
/// Requires that `start + sub.len() <= main.len()`.
fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // If the subarray would overflow `main`, it can't match.
    if start + sub.len() > main.len() {
        return false;
    }
    // Compare elements one by one.
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

/// Returns true if and only if `sub` is a contiguous subarray of `main`.
/// The empty `sub` always qualifies. If `sub` is longer than `main`, returns false.
fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // An empty subarray is always found.
    if sub.is_empty() {
        return true;
    }
    let n = main.len();
    let m = sub.len();
    // If sub is longer than main, it cannot be contained.
    if m > n {
        return false;
    }
    // Try every possible starting position.
    // The last valid start is n - m.
    for start in 0..=(n - m) {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}

